CREATE POLICY admin_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='quote-photos' AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.list_open_slots() RETURNS TABLE(id uuid,starts_at timestamptz,ends_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.starts_at,a.ends_at FROM public.availability a WHERE a.enabled AND a.starts_at>now() AND NOT EXISTS(SELECT 1 FROM public.quote_requests q WHERE q.slot_id=a.id AND q.status IN('pending','confirmed')) ORDER BY a.starts_at LIMIT 100 $$;
GRANT EXECUTE ON FUNCTION public.list_open_slots() TO anon,authenticated;
CREATE FUNCTION public.prevent_overlapping_slots() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(671001); IF NEW.enabled AND EXISTS(SELECT 1 FROM public.availability WHERE id<>NEW.id AND enabled AND starts_at<NEW.ends_at AND ends_at>NEW.starts_at) THEN RAISE EXCEPTION 'Un créneau existe déjà sur cette période'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_overlaps BEFORE INSERT OR UPDATE ON public.availability FOR EACH ROW EXECUTE FUNCTION public.prevent_overlapping_slots();